window.SAQ_PAPER_QUESTIONS["2017-2-northern-sydney"]=[{"number":1,"title":"","stemText":"(21 marks) With regard to skin and soft tissue infections","parts":[{"id":"a","label":"Part A","prompt":"List 5 non-infectious conditions that masquerade as unilateral leg cellulitis and\nindicate the symptoms/signs and/or tests that help to differentiate the condition from cellulitis (10 marks) Cellulitis mimic Differentiating symptoms/signs/investigations"},{"id":"b","label":"Part B","prompt":"List 3 choices of oral antibiotic which cover Streptococcus pyogenes and\nStaphylococcus aureus (3 marks)"},{"id":"c","label":"Part C","prompt":"Briefly explain the pharmacodynamic advantage conferred by combining a beta- lactam antibiotic with: (a) Probenecid (2 marks) (b) Clavulanic acid (2 marks)"},{"id":"d","label":"Part D","prompt":"Regarding the management of abscesses, write short notes on the role of the addition of an antibiotic to simple incision and drainage of the abscess (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">indicate the symptoms/signs and/or tests that help to differentiate the condition</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Flucloxacillin 500-1000mg QID</div><div class=\"answer-line\">Cephalexin 500-1000mg QID</div><div class=\"answer-line\">Clindamycin 450mg TDS</div><div class=\"answer-line\">Briefly explain the pharmacodynamic advantage conferred by combining a beta-</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">lactam antibiotic with:</div><div class=\"answer-line\">(a) Probenecid (2 marks)</div><div class=\"answer-line\">• Decreases renal excretion of drugs that undergo active tubular secretion –</div><div class=\"answer-line\">especially weak acids &amp; including B-lactam antibiotics. Pharmacokinetic</div><div class=\"answer-line\">principles \u0001 longer period where concentration of drug stays above MIC</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">• Generally considered that I&amp;D is sufficient and antibiotics are not required.</div><div class=\"answer-line\">• However, with surrounding cellulitis may be indicated.</div><div class=\"answer-line\">• Further, there is a small benefit of the addition of Bactrim (7% reduction in “failure”</div><div class=\"answer-line\">of treatment) – which has to be balanced against the risk of antibiotic adverse</div><div class=\"answer-line\">effects.</div><div class=\"answer-line\">• Higher prevalence of Staph aureus and in some populations resistant forms means if</div><div class=\"answer-line\">an antibiotic is used it should cover MSSA e.g. bactrim</div><div class=\"answer-line\">NSW Fellowship Course – NSLHD SAQ December 2017</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":2,"title":"","stemText":"A 65 year old male presents with severe sudden onset left flank pain. He is pale, sweaty and agitated.\n\nVital signs:\n\nGCS 14\nAutomated BP 160/145mmHg, palpable brachial pulse (but not radial)\nP 130 bpm\n\nRR 27 bpm\nCentral CR 5 sec","parts":[{"id":"a","label":"Part A","prompt":"List 4 differential diagnoses (4 marks)"},{"id":"b","label":"Part B","prompt":"Why is there discrepancy between palpable pulses and automated BP and what is your action (3 marks)"},{"id":"c","label":"Part C","prompt":"You suspect a ruptured abdominal aortic aneurysm. List 2 pros and 2 cons for ultrasound and CT imaging (8 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• Lumbar back pain</div><div class=\"answer-line\">• Epidural abscess with septic shock</div><div class=\"answer-line\">• Ruptured AAA</div><div class=\"answer-line\">• Aortic dissection with rupture</div><div class=\"answer-line\">• Renal colic</div><div class=\"answer-line\">• Spontaneous retroperitoneal haemorrhage</div><div class=\"answer-line\">• Perforated DU</div><div class=\"answer-line\">Why is there discrepancy between palpable pulses and automated BP and what is your</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• The automated oscillometric BP is unreliable in very low BP and will often give</div><div class=\"answer-line\">extraneous results</div><div class=\"answer-line\">• Action: perform manual BP and/or site arterial line at appropriate time</div><div class=\"answer-line\">NSW Fellowship Course – NSLHD SAQ December 2017</div><div class=\"answer-line\">You suspect a ruptured abdominal aortic aneurysm. List 2 pros and 2 cons  for</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Ultrasound</div><div class=\"answer-line\">• Pro: fast, no radiation, bedside, rapidly rule in other diagnoses</div><div class=\"answer-line\">• Con: requires training, specificity/sens level not as good as CT, not good for detecting</div><div class=\"answer-line\">type/extent of AAA or surgical planning in terms of EVAR/open repair</div><div class=\"answer-line\">CT</div><div class=\"answer-line\">• Pro: high sensitivity/specificity, accurate-extent/type of aneurysm, allows planning for</div><div class=\"answer-line\">vascular surgeons. Accurate at ruling in/out other diagnoses</div><div class=\"answer-line\">• Con: radiation, logistics-potential deterioration in CT scanner, potential for AKI if already</div><div class=\"answer-line\">severe renal impairment although not critically important. Lag time to images and</div><div class=\"answer-line\">interpretation/report</div><div class=\"answer-line\">NSW Fellowship Course – NSLHD SAQ December 2017</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":3,"title":"","stemText":"A 5 year old is brought to the Emergency Department with worsening asthma for the last 4\nhours.","parts":[{"id":"a","label":"Part A","prompt":"What are four clinical features of life threatening asthma (4 marks)"},{"id":"b","label":"Part B","prompt":"List your immediate pharmacological management (3 marks)"},{"id":"c","label":"Part C","prompt":"Despite appropriate escalation of management the patient's condition deteriorates over several hours and they are intubated in the ED. Complete the following table (5 marks)"},{"id":"e","label":"Part E","prompt":"After connecting to the ventilator the patient suddenly deteriorates becoming progressively hypotensive and tachycardic. Give three possible causes (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"removedNonQuestionResponseFragments":["E ratio"],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• Confusion</div><div class=\"answer-line\">• Coma</div><div class=\"answer-line\">• Exhaustion</div><div class=\"answer-line\">• Poor respiratory effort</div><div class=\"answer-line\">• Silent chest</div><div class=\"answer-line\">• Cyanosis</div><div class=\"answer-line\">• Hypotension</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• Ventolin 6 puffs by MDI or nebuliser Q20min x3</div><div class=\"answer-line\">• Ipratropium bromide 4 puffs Q20 min</div><div class=\"answer-line\">• Prednisolone 1mg/kg (methylpred/hydrocort alternatives)</div><div class=\"answer-line\">NSW Fellowship Course – NSLHD SAQ December 2017</div><div class=\"answer-line\">Despite appropriate escalation of management the patient&#x27;s condition deteriorates over</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Parameter</div><div class=\"answer-line\">Setting</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">After connecting to the ventilator the patient suddenly deteriorates becoming</div><div class=\"answer-line\">progressively hypotensive and tachycardic. Give three possible causes (3 marks)</div><div class=\"answer-line\">• dynamic hyperinflation/gas trapping, tension pneumothorax, effect of induction agents,</div><div class=\"answer-line\">other (hypovolaemia, equipment failure - tube dislodgement/O2 not connected)</div><div class=\"answer-line\">NSW Fellowship Course – NSLHD SAQ December 2017</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":4,"title":"","stemText":"You are the senior doctor in charge of a tertiary ED at 3pm when Ambulance Control state that there has been an explosion nearby.","parts":[{"id":"a","label":"Part A","prompt":"What 5 pieces of information are important to obtain from Ambulance Control (5 marks)"},{"id":"b","label":"Part B","prompt":"List 7 steps that you should perform after receiving this phone call (7 marks)"},{"id":"c","label":"Part C","prompt":"Patients start arriving rapidly on foot and by ambulance. Using a triage sieve, classify (red, yellow, green) the following patients (4 marks) 1. Female 40s, lying on ambulance stretcher, GCS 14, RR 33, BP 105/80, P 110 2. Male 30s, limping up to triage unassisted, GCS 15, RR 26, BP 95/50, P 105 3. Female 20s, sitting in a wheelchair, obvious compound tibial fracture, GCS 15, RR 28,\nP 120\n4. Male 50s, lying on stretcher, GCS 13, RR 25, BP 105/60, P 110"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">(METHANE acronym)</div><div class=\"answer-line\">• Confirm that a Major Incident has been declared</div><div class=\"answer-line\">• Exact location</div><div class=\"answer-line\">• Type of incident</div><div class=\"answer-line\">• Hazards</div><div class=\"answer-line\">• (Access/egress)</div><div class=\"answer-line\">• Number of casualties (total and likely coming to your facility)</div><div class=\"answer-line\">• (Emergency services present/required)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">NSW Fellowship Course – NSLHD SAQ December 2017</div><div class=\"answer-line\">• Declare a Major Incident as per Major Incident Protocol in your hospital \u0001 should</div><div class=\"answer-line\">cascade to executive/senior management to co-ordinate roles outside ED</div><div class=\"answer-line\">• Find/follow major incident role-description cards</div><div class=\"answer-line\">• Take role of Medical Co-ordinator or Senior Emergency Physician until/unless another</div><div class=\"answer-line\">more appropriate person can</div><div class=\"answer-line\">• Consider need for decontamination of all patients prior to entering ED</div><div class=\"answer-line\">• Close all other entry points to ED except one triage route</div><div class=\"answer-line\">• Liaise with senior nursing and senior management to form key roles: triage officer,</div><div class=\"answer-line\">resuscitation teams, acute patients treating staff, green walking patients treating staff</div><div class=\"answer-line\">• Assess current ED staffing and potential staffing (who can be called in)</div><div class=\"answer-line\">• Identify areas to see Resus (red), Acute (yellow) and Walking (green) patients.</div><div class=\"answer-line\">• Clear the emergency department of as many patients as possible</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Patients start arriving rapidly on foot and by ambulance. Using a triage sieve, classify</div><div class=\"answer-line\">(red, yellow, green) the following patients (4 marks)</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":5,"title":"","stemText":"Precipitous deterioration can occur around the time of intubation in several specific situations.","parts":[{"id":"a","label":"Part A","prompt":"Explain the pathophysiology of the cardiovascular collapse that can occur at induction of a patient with severe aortic stenosis (4 marks)"},{"id":"b","label":"Part B","prompt":"Cardiovascular collapse can occur at the induction, intubation and ventilation of a patient with severe metabolic acidosis. Outline measures you would take to prevent this from occurring (4 marks)"},{"id":"c","label":"Part C","prompt":"Explain the pathophysiology of the cardiovascular collapse that can occur at induction, intubation and ventilation of a severe asthmatic (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• AS leads to concentric LV hypertrophy and a poorly compliant ventricle which is highly</div><div class=\"answer-line\">dependent on pre-load for adequate diastolic filling</div><div class=\"answer-line\">o If you drop the pre-load (or the aortic end-diastolic pressure) – e.g. by</div><div class=\"answer-line\">vasodilation - LV filling is poor &amp; stroke volume low</div><div class=\"answer-line\">• Also dependent on diastolic filling time – so causing tachycardia is also bad (atrial</div><div class=\"answer-line\">fibrillation is very bad as highly dependent on atrial “kick” – normal heart = 20% of</div><div class=\"answer-line\">diastolic ventricular filling but in AS up to 40%)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Cardiovascular collapse can occur at the induction, intubation and ventilation of a</div><div class=\"answer-line\">patient with severe metabolic acidosis.  Outline measures you would take to prevent</div><div class=\"answer-line\">this from occurring (4 marks)</div><div class=\"answer-line\">• Patients typically have respiratory compensation ++, need to match their minute volume</div><div class=\"answer-line\">peri-intubation or acidosis precipitously worsens \u0001 poor myocardial contractility,</div><div class=\"answer-line\">diminished catechol responsiveness</div><div class=\"answer-line\">NSW Fellowship Course – NSLHD SAQ December 2017</div><div class=\"answer-line\">• Pre-oxygenate with their spontaneous resps (or NIV-assisted at matched RR), note</div><div class=\"answer-line\">ETCO2 (and try not to let it climb), RSI but with breaths delivered throughout induction</div><div class=\"answer-line\">phase (no apnoea), rapid intubation, match previous minute volume</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Explain the pathophysiology of the cardiovascular collapse that can occur at induction,</div><div class=\"answer-line\">intubation and ventilation of a severe asthmatic (4 marks)</div><div class=\"answer-line\">• Often ill for quite a while prior to arrival with decreased oral intake so under-volume to</div><div class=\"answer-line\">begin with</div><div class=\"answer-line\">• Typically have maximal endogenous sympathetic outflow – this decreases with induction</div><div class=\"answer-line\">\u0001 relative vasodilation</div><div class=\"answer-line\">• Positive pressure ventilation with inadequate expiratory time \u0001 raised ITP, decreased</div><div class=\"answer-line\">VR etc</div><div class=\"answer-line\">• Consider pneumothorax</div><div class=\"answer-line\">NSW Fellowship Course – NSLHD SAQ December 2017</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":6,"title":"","stemText":"A 62 year old man presents with a cold, painful, numb left leg. You suspect an acute\nischaemic limb.","parts":[{"id":"a","label":"Part A","prompt":"List 4 features on history that would suggest acute arterial embolism rather than\nthrombosis as the cause (4 marks)"},{"id":"b","label":"Part B","prompt":"List 4 features on examination that would suggest acute arterial embolism rather than\nthrombosis as the cause (4 marks)"},{"id":"c","label":"Part C","prompt":"Name 2 revascularisation strategies (2 marks)"},{"id":"d","label":"Part D","prompt":"Name 4 post reperfusion complications that may arise (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• Minimal history of atherosclerotic disease</div><div class=\"answer-line\">• No or minimal history of claudication</div><div class=\"answer-line\">• Acute or sudden onset of symptoms</div><div class=\"answer-line\">• History of AF</div><div class=\"answer-line\">• History of valvular heart disease (mitral vlv stenosis) or prosthetic valve</div><div class=\"answer-line\">• known atrial myxoma</div><div class=\"answer-line\">• known endocarditis</div><div class=\"answer-line\">• known LV aneurysm or cardiomyopathy</div><div class=\"answer-line\">List 4 features on examination that would suggest acute arterial embolism rather than</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• Presence of AF</div><div class=\"answer-line\">• Clinical signs of bacterial endocarditis</div><div class=\"answer-line\">• Heart murmurs suggesting valvular disease</div><div class=\"answer-line\">• Presence of abdominal aortic, femoral or popliteal aneurysm</div><div class=\"answer-line\">• Degree of demarcation sharp rather than more diffuse in thrombotic disease</div><div class=\"answer-line\">• Absence of chronic ischaemic changes in limb (e.g. wasting, hair loss, skin atrophy</div><div class=\"answer-line\">ulceration)</div><div class=\"answer-line\">• Good proximal and contralateral pulses</div><div class=\"answer-line\">• Site of demarcation at major bifurcations of arteries</div><div class=\"answer-line\">• More extensive gangrene or more obviously limb threatening</div><div class=\"answer-line\">NSW Fellowship Course – NSLHD SAQ December 2017</div><div class=\"answer-line\">Name 2 revascularisation strategies (2 marks)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">• Intra-arterial thrombolysis</div><div class=\"answer-line\">• Catheter embolectomy</div><div class=\"answer-line\">• Surgical embolectomy</div><div class=\"answer-line\">• Arterial bypass surgery</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">• Compartment syndrome</div><div class=\"answer-line\">• Hyperkalaemia</div><div class=\"answer-line\">• Acidosis</div><div class=\"answer-line\">• Re-occlusion and ischaemia</div><div class=\"answer-line\">• Rhabdomyolysis, myoglobinuria</div><div class=\"answer-line\">• Renal failure</div><div class=\"answer-line\">• Myocardial depression &amp; hypotension</div><div class=\"answer-line\">NSW Fellowship Course – NSLHD SAQ December 2017</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":7,"title":"","stemText":"You are a retrieval doctor tasked to a scene of a suspected electrical injury of a technician working at an electrical substation. On approach, he can be seen 5 metres from the potential source and is wet from the overhead rain. The patient is groaning and you note a burn on his right hand, holes in the soles of his shoes, and partially torn and charred clothing.","parts":[{"id":"a","label":"Part A","prompt":"Outline 5 initial management priorities at the scene (5 marks)"},{"id":"b","label":"Part B","prompt":"List 4 features of the history or examination that suggest significant injury (4 marks)"},{"id":"c","label":"Part C","prompt":"Write short notes on 3 limb and 3 systemic complications that will need to be\nconsidered in the ED (6 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• safe approach/scene safety – paramedic, fire (responder safety directed by wider team,</div><div class=\"answer-line\">high risk of provider injury so must not approach until all clear)</div><div class=\"answer-line\">• trauma assessment approach with meaningful interventions (risk of trauma, avoid</div><div class=\"answer-line\">delays)</div><div class=\"answer-line\">• humanitarian – analgesia/anaesthesia (expectation of severe pain)</div><div class=\"answer-line\">• plan destination – trauma/burns centre (avoid secondary transfer)</div><div class=\"answer-line\">• fluid management, temperature management (Parklands not valid, risk of hypothermia</div><div class=\"answer-line\">from skin burns, wet patient exposed outdoors)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• potential high voltage</div><div class=\"answer-line\">• wet skin</div><div class=\"answer-line\">• thrown distance from the site with possible associated trauma</div><div class=\"answer-line\">NSW Fellowship Course – NSLHD SAQ December 2017</div><div class=\"answer-line\">• cardiac pathway of current</div><div class=\"answer-line\">• arc burns with flash/flame injury</div><div class=\"answer-line\">• non-mobile patient</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Write short notes on 3 limb and 3 systemic complications that will need to be</div><div class=\"answer-line\">considered in the ED (6 marks)</div><div class=\"answer-line\">Limb</div><div class=\"answer-line\">• vasospasm/thrombosis – loss of pulse (dopplers, angiography, vascular consult)</div><div class=\"answer-line\">• compartment syndrome – tense painful compartment, 6 P’s late (ortho/burns consult,</div><div class=\"answer-line\">fasciotomy)</div><div class=\"answer-line\">• avulsion # - pain/swelling at insertion sites (2ry survey X rays, immobilise, ortho consult)</div><div class=\"answer-line\">• trauma from being thrown by current (2ry survey, consult as required)</div><div class=\"answer-line\">Systemic</div><div class=\"answer-line\">• cardiac arrhythmias (early, late) – require ECG monitoring (exclude hyperK+, Echo)</div><div class=\"answer-line\">• rhabdomyolysis – myoglobinuria, elevated CK (fluid Mx, diuresis)</div><div class=\"answer-line\">• traumatic injury – clinical, radiological</div><div class=\"answer-line\">• altered LOC, seizures, coma – clinical, CTB (neuroprotective measures)</div><div class=\"answer-line\">• skin burns (arc/flash/flame) – clinical (fluids, analgesia, tetanus, temp Mx, ulcer</div><div class=\"answer-line\">prophylaxis, ngt, consult burns)</div><div class=\"answer-line\">NSW Fellowship Course – NSLHD SAQ December 2017</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":8,"title":"","stemText":"A 72 year old female presents with jaw pain and inability to close her mouth after yawning.","parts":[{"id":"a","label":"Part A","prompt":"What is the most likely diagnosis (1 mark)"},{"id":"b","label":"Part B","prompt":"List three risk factors for this (3 marks)"},{"id":"c","label":"Part C","prompt":"List three mechanisms that can cause this problem (3 marks)"},{"id":"d","label":"Part D","prompt":"Describe two techniques for reduction (no need to describe analgesia/anaesthesia) (6 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• Anterior TMJ dislocation</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• Previous TMJ dislocation</div><div class=\"answer-line\">• Ligamentous laxity syndrome eg Ehler Danlos or Marfan</div><div class=\"answer-line\">• TMJ dysfunction or previous trauma</div><div class=\"answer-line\">List three mechanisms that can cause this problem (3 marks)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">• Iatrogenic: Dental procedures, laryngoscopy</div><div class=\"answer-line\">• Extreme mouth opening eg yawning, eating, vomiting, laughing, oral sex…</div><div class=\"answer-line\">• Seizures</div><div class=\"answer-line\">• Dystonic drug reaction</div><div class=\"answer-line\">• Trauma</div><div class=\"answer-line\">NSW Fellowship Course – NSLHD SAQ December 2017</div><div class=\"answer-line\">Describe two techniques for reduction (no need to describe analgesia/anaesthesia) (6</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">marks)</div><div class=\"answer-line\">• Traditional: Patient seated with head supported posteriorly. Physician stands in front</div><div class=\"answer-line\">with elbows flexed. Mandible held with gloved thumbs intraorally just lateral to lower</div><div class=\"answer-line\">molars. Down and backward manipulation</div><div class=\"answer-line\">• Modified traditional. Physician stands behind the patient with hands in the same</div><div class=\"answer-line\">position. Down and backwards pressure from thumbs</div><div class=\"answer-line\">• Syringe: Reduce one side at a time. 5 or 10ml syringe between posterior upper and</div><div class=\"answer-line\">lower molars. Patient bites down on syringe whilst it is rolled back and forth between</div><div class=\"answer-line\">the teeth until reduced. Typically other side reduces spontaneously</div><div class=\"answer-line\">• Wrist pivot: Physician faces patient, grasps mandible with thumbs under chin and</div><div class=\"answer-line\">fingers on occlusal surfaces lower molars. Upward force with thumbs and downward</div><div class=\"answer-line\">pressure by fingers. Pivots wrists forwards</div><div class=\"answer-line\">• Gag: Elicit gag reflex and reflex inhibition of muscles may result in relocation. Beware</div><div class=\"answer-line\">vomiting</div><div class=\"answer-line\">NSW Fellowship Course – NSLHD SAQ December 2017</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":9,"title":"","stemText":"IMAGES FOR THIS QUESTION ARE IN THE PROPS BOOKLET - IMAGES A-F","parts":[{"id":"a","label":"Part A","prompt":"Which of the M-mode images (IMAGE A or B) demonstrates a pneumothorax? (1 mark)"},{"id":"b","label":"Part B","prompt":"Why is the other image NOT consistent with pneumothorax (4 marks)"},{"id":"c","label":"Part C","prompt":"Which of the M-mode IVC images (IMAGES C or D) is consistent with a tension pneumothorax? (1 mark)"},{"id":"d","label":"Part D","prompt":"Why is the other image NOT consistent with pneumothorax? (4 marks)"},{"id":"e","label":"Part E","prompt":"Which image (IMAGE E or F) is consistent with pleural sliding? (1 mark)"},{"id":"f","label":"Part F","prompt":"Why is the other image NOT consistent with pleural sliding? (4 marks)"}],"propPages":["asset:img44283f8c714b554184","asset:img6bd9a589c734020a92","asset:img7a3ef19471ebe6b754","asset:imgfcaa3e02c5f668bfb4","asset:img0992d3d8c59e021f55","asset:img2864a2b8d2e4dd8ab8"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">i.</div><div class=\"answer-line\">• A</div><div class=\"answer-line\">ii.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• Image B demonstrates ‘lung pulse’ [repeated vertical lines that are seen only</div><div class=\"answer-line\">below the</div><div class=\"answer-line\">pleural line].</div><div class=\"answer-line\">• This represents the lung’s ‘jiggle’ as oxygenated blood fills it. This artefact is</div><div class=\"answer-line\">useful because it’s not seen in pneumothorax. It’s seen only in lung, even</div><div class=\"answer-line\">unventilated</div><div class=\"answer-line\">lung.</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">• D</div><div class=\"answer-line\">iv.</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">• Image C demonstrates an IVC that collapses almost completely on inspiration,</div><div class=\"answer-line\">therefore</div><div class=\"answer-line\">the intrathoracic pressure is very low on inspiration.</div><div class=\"answer-line\">• By contrast, in image D the IVC is behaving like a ‘lead pipe’ and is almost</div><div class=\"answer-line\">unchanged</div><div class=\"answer-line\">NSW Fellowship Course – NSLHD SAQ December 2017</div><div class=\"answer-line\">with respiration, suggesting either fluid overload or ++ high filling pressures as in</div><div class=\"answer-line\">the</div><div class=\"answer-line\">case of all obstructive shock [this IVC would also be seen in pericardial</div><div class=\"answer-line\">tamponade or</div><div class=\"answer-line\">massive PE]</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">v.</div><div class=\"answer-line\">• E</div></section><section class=\"answer-part\"><h5>Part F</h5><div class=\"answer-line\">vi.</div><div class=\"answer-line\">• Image F actually is an M mode image of cardiac motion [the right ventricle free</div><div class=\"answer-line\">wall just</div><div class=\"answer-line\">under the chest wall]. The clues are [a] the lung should be bright but this is dark</div><div class=\"answer-line\">[because filled with blood], and [b] the zig-zag direction of movement represents</div><div class=\"answer-line\">updown movement toward and away from the chest wall. This is not something</div><div class=\"answer-line\">the lung</div><div class=\"answer-line\">does! [Except in effusions, but that’s a different story and would be in time with</div><div class=\"answer-line\">breathing, not the heartbeat]</div><div class=\"answer-line\">NSW Fellowship Course – NSLHD SAQ December 2017</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":10,"title":"","stemText":"A 62 year old man is brought to ED having been found asleep in the garden in the sun. He is agitated, combative, with no focal neurology or signs of trauma.\n\nVital signs\n\nTemp 41 deg Celsius\nP 118 bpm\n\nBP 90/40 mmHg\n\nRR 20 bpm\n\nSaO2 98% RA\n\nGCS 14 (E4V4M6)","parts":[{"id":"a","label":"Part A","prompt":"List 4 possible diagnoses starting with the most likely (4 marks)"},{"id":"b","label":"Part B","prompt":"List 3 separate heat related illnesses and their diagnostic criteria/main clinical findings (6 marks)"},{"id":"c","label":"Part C","prompt":"List 3 potential ways of cooling this patient and 1 pro and con of each (6 marks)"},{"id":"d","label":"Part D","prompt":"List 4 potential complications of this condition from separate organ systems (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">i.</div><div class=\"answer-line\">• Heat stroke</div><div class=\"answer-line\">• Sepsis (LRTI, UTI, skin etc)</div><div class=\"answer-line\">• CNS infection (meningitis/encephalitis/brain abscess)</div><div class=\"answer-line\">• Toxidrome (anticholinergic, sympathomimetic, NMS – less likely)</div><div class=\"answer-line\">• Drug withdrawal – alcohol , opiates</div><div class=\"answer-line\">• Neuro - Non-convulsive status epilepticus, ICH /thalamic bleed</div><div class=\"answer-line\">• Endocrine – thyroid storm, DKA</div><div class=\"answer-line\">ii.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">NSW Fellowship Course – NSLHD SAQ December 2017</div><div class=\"answer-line\">• Heat stroke (core temp &gt; 40 (or 40.6) + CNS dysfunction)</div><div class=\"answer-line\">• Heat exhaustion (any heat relates illness + significant volume depletion with normal</div><div class=\"answer-line\">mental status)</div><div class=\"answer-line\">• Heat cramps (painful, involuntary, spasmodic skeletal muscle contractions)</div><div class=\"answer-line\">• Prickly heat (pruritic, maculopapular, erythematous rash over clothed areas of the body)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">iii.</div><div class=\"answer-line\">• Cooled fluids – readily available, limited efficacy in dropping temp</div><div class=\"answer-line\">• Evaporative – simple, effective, non-invasive and readily available method in ED, may lead</div><div class=\"answer-line\">to shivering</div><div class=\"answer-line\">• Immersion – very effective but not practical for most patients in resus (can consider</div><div class=\"answer-line\">immersing hands/feet)</div><div class=\"answer-line\">• Ice packs to necks/axillae/groin – readily available, non-invasive, need to be replaced</div><div class=\"answer-line\">regularly, not as effective as others but can be combined with eg evaporation</div><div class=\"answer-line\">• Cooling blanket – not readily available, preclude use of evaporative cooling, works too</div><div class=\"answer-line\">slowly</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">• ECMO/CPB – most effective but invasive ++, delays to set up and not available most EDs</div><div class=\"answer-line\">NSW Fellowship Course – NSLHD SAQ December 2017</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":11,"title":"","stemText":"You are interested in establishing an in-situ simulation program in your tertiary Emergency Department.","parts":[{"id":"a","label":"Part A","prompt":"List 3 components of your pre-brief (i.e. before participants enter the scenario) that\ncreate a “safe learning environment” for participants in in-situ simulation. (3 marks)"},{"id":"b","label":"Part B","prompt":"Outline 3 key components of your framework for debriefing a simulation scenario (3\nmarks)"},{"id":"c","label":"Part C","prompt":"Identify 4 potential barriers or risks to running in-situ simulation and a mitigating\nsolution for each barrier (8 marks) Potential Barrier/Risk Solution"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">1. Formative rather than summative</div><div class=\"answer-line\">-Identify areas for learning and improvement; not an assessment of individual</div><div class=\"answer-line\">performance</div><div class=\"answer-line\">2. Orientation to the environment, equipment, drugs, manikin, etc</div><div class=\"answer-line\">3. Expectations of participants</div><div class=\"answer-line\">NSW Fellowship Course – NSLHD SAQ December 2017</div><div class=\"answer-line\">-Express that the scenario is based on a clinical case, not designed to “trip-</div><div class=\"answer-line\">up” participants. Participants are expected to perform in their usual role and</div><div class=\"answer-line\">at their usual level of practice.</div><div class=\"answer-line\">4. Confidentiality</div><div class=\"answer-line\">-their individual performance will not be discussed outside of the session</div><div class=\"answer-line\">Outline 3 key components of your framework for debriefing a simulation scenario (3</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">marks)</div><div class=\"answer-line\">1. Reactions phase</div><div class=\"answer-line\">-important that trainees first discuss reactions generated (emotions/feelings) from</div><div class=\"answer-line\">being in the scenario. If this is not addressed, they will not be able to engage in</div><div class=\"answer-line\">reflective learning</div><div class=\"answer-line\">2. Identify components performed well and those that were challenging</div><div class=\"answer-line\">-Learning needs identified by participants themselves; reflective learning</div><div class=\"answer-line\">-Learner/participant centred approach</div><div class=\"answer-line\">3. Analysis</div><div class=\"answer-line\">-understanding of participants framework/models for decisions made</div><div class=\"answer-line\">-use of advocacy inquiry, delta-plus principles</div><div class=\"answer-line\">-address technical (Clinical Knowledge) and non-technical (Communication and</div><div class=\"answer-line\">Human Factors)</div><div class=\"answer-line\">4. Summarise/”Take-home points”</div><div class=\"answer-line\">-important to wrap-up session with clear statements on specific learning objectives</div><div class=\"answer-line\">that were identified</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Risk / issue</th><th>Mitigation / management</th></tr></thead><tbody><tr><td>Identify 4 potential barriers or risks to running in-situ simulation and a mitigating</td><td></td></tr><tr><td>solution for each barrier (8 marks)</td><td></td></tr><tr><td>Potential Barrier/Risk</td><td>Solution</td></tr><tr><td>Simulation equipment/drugs used on “real</td><td>• Clearly labelled simulation equipment</td></tr><tr><td>patients” (ie decommissioned equipment or out-</td><td>• Simulation equipment stored or locked</td></tr><tr><td>of-date drugs)</td><td>away</td></tr><tr><td>Reluctance of participation</td><td>• Trainees are aware when it’s happening</td></tr><tr><td>(set time/date)</td><td></td></tr><tr><td>•</td><td>Encouraged/supported by consultant</td></tr><tr><td>NSW Fellowship Course – NSLHD SAQ December 2017</td><td></td></tr><tr><td>group/DEMT</td><td></td></tr><tr><td>Reluctance to perform session when department</td><td>• Sessions to be conducted at times of</td></tr><tr><td>busy</td><td>lower patient volume/acuity (eg</td></tr><tr><td>mornings)</td><td></td></tr><tr><td>•</td><td>Sessions contacted during periods of</td></tr><tr><td>maximal staffing (cross-over between</td><td></td></tr><tr><td>shifts)</td><td></td></tr><tr><td>•</td><td>Agreed upon criteria for cancelling</td></tr><tr><td>session (eg patient waiting numbers,</td><td></td></tr><tr><td>resus patients TBS)</td><td></td></tr><tr><td>Disturbance of patients/relatives in nearby</td><td>• Make patients/relatives nearby aware</td></tr><tr><td>clinical areas</td><td>(communicate or signs) that mock</td></tr><tr><td>training is occurring</td><td></td></tr><tr><td>Available space in clinical area</td><td>• Have a dedicated/protected area within</td></tr><tr><td>the department for simulation</td><td></td></tr><tr><td>Lack of equipment/funding</td><td>• Perform low fidelity simulations with</td></tr><tr><td>specific learning outcomes</td><td></td></tr><tr><td>•</td><td>Keep decommissioned or out-of-date</td></tr><tr><td>equipment for sim use</td><td></td></tr><tr><td>NSW Fellowship Course – NSLHD SAQ December 2017</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":12,"title":"","stemText":"A 25 year old man presents 6 hours after a SCUBA dive with a possible decompression\nsickness (DCS)","parts":[{"id":"a","label":"Part A","prompt":"List 6 questions specific to diving that you should ask in your history (6 marks)"},{"id":"b","label":"Part B","prompt":"Complete the table listing 3 symptoms or signs of DCS in each"},{"id":"c","label":"Part C","prompt":"Complete the table contrasting DCS and Arterial Gas Embolism ("}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">i.</div><div class=\"answer-line\">• Dive profile (ideally from log book or computer)  – depth, times, ascent rates, surface</div><div class=\"answer-line\">intervals, safety/decompression stops</div><div class=\"answer-line\">• Dives in excess of tables?</div><div class=\"answer-line\">• Multiple dives in one day?</div><div class=\"answer-line\">• Altitude/flight since dive</div><div class=\"answer-line\">• Any problems during descent/ascent  – problems equalising? Equipment issues?</div><div class=\"answer-line\">Incidents?</div><div class=\"answer-line\">• Delay to symptom onset after leaving water</div><div class=\"answer-line\">• Previous dive experience</div><div class=\"answer-line\">• Previous dive-related illness</div><div class=\"answer-line\">ii.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Category</td><td>Symptom/Sign</td></tr><tr><td>Neurological</td><td>Weakness, headache, paralysis, dizziness, visual</td></tr><tr><td colspan=\"2\">disturbance, vertigo, altered LOC, paraesthesia,</td></tr><tr><td colspan=\"2\">urinary retention</td></tr><tr><td>Other</td><td>SOB, rash, itching, joint/muscle aches, chest</td></tr><tr><td colspan=\"2\">pain</td></tr><tr><td colspan=\"2\">iii.</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">NSW Fellowship Course – NSLHD SAQ December 2017</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":13,"title":"","stemText":"A 42 year old man has developed a febrile illness one week after returning from a business trip to Papua New Guinea.","parts":[{"id":"a","label":"Part A","prompt":"What questions specific to this case should form part of the history that you will\n• btain? (6 marks)"},{"id":"b","label":"Part B","prompt":"Describe how the diagnosis of malaria can be established (3 marks)"},{"id":"c","label":"Part C","prompt":"Plasmodium falciparum has several characteristics that are markedly different to the\n• ther Plasmodia species. Briefly describe 3 differences (3 marks)"},{"id":"d","label":"Part D","prompt":"List 4 complications that occur in severe P falciparum infection (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">i.</div><div class=\"answer-line\">obtain? (6 marks)</div><div class=\"answer-line\">Travel history – where exactly, urban/rural, resort/airconditioning etc, duration, prophylaxis</div><div class=\"answer-line\">(malaria/other), mosquito protection/bites, other exposures, sexual activities</div><div class=\"answer-line\">History of current illness – symptom onset, cyclical fevers, rash.  System review - a/n/v/d,</div><div class=\"answer-line\">blood in stool, abdo pain – URTI/LRTI/ENT symptoms etc.  Any self-administered Rx</div><div class=\"answer-line\">[ General history – normal health, PHx, meds, allergies …altogether only constitute one</div><div class=\"answer-line\">point. Important but excluded by the question “…specific to this case…”]</div><div class=\"answer-line\">ii.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• Films – thin (for speciation), thick (if no parasites seen on thin film). One negative</div><div class=\"answer-line\">does not exclude Dx – protocols vary but typically repeat 3-4 times over 24h</div><div class=\"answer-line\">• Antigen tests – esp for PF</div><div class=\"answer-line\">iii.</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">obtain? (6 marks)</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Travel history – where exactly, urban/rural, resort/airconditioning etc, duration, prophylaxis</div><div class=\"answer-line\">(malaria/other), mosquito protection/bites, other exposures, sexual activities</div><div class=\"answer-line\">History of current illness – symptom onset, cyclical fevers, rash.  System review - a/n/v/d,</div><div class=\"answer-line\">blood in stool, abdo pain – URTI/LRTI/ENT symptoms etc.  Any self-administered Rx</div><div class=\"answer-line\">[ General history – normal health, PHx, meds, allergies …altogether only constitute one</div><div class=\"answer-line\">point. Important but excluded by the question “…specific to this case…”]</div><div class=\"answer-line\">ii.</div><div class=\"answer-line\">• Films – thin (for speciation), thick (if no parasites seen on thin film). One negative</div><div class=\"answer-line\">does not exclude Dx – protocols vary but typically repeat 3-4 times over 24h</div><div class=\"answer-line\">• Antigen tests – esp for PF</div><div class=\"answer-line\">iii.</div><div class=\"answer-line\">other Plasmodia species. Briefly describe 3 differences (3 marks)</div><div class=\"answer-line\">NSW Fellowship Course – NSLHD SAQ December 2017</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":14,"title":"","stemText":"A 62 year-old man is brought to your ED after an assault during a home invasion. He has\nbeen stabbed in the anterior right side of neck and was pushed down a steep flight of stairs with possible head and neck injuries due to the fall. Initial assessment:\n\nGCS\n10; combative\n\nHR\n125 per minute\n\nBP\n105/65 mmHg Head: Right parietal large boggy swelling Neck: Wound at right side of anterior neck, extends from medial aspect of clavicle to level of cricoid, extensive haemorrhage","parts":[{"id":"a","label":"Part A","prompt":"List 5 immediate management priorities? (5 marks)"},{"id":"b","label":"Part B","prompt":"List 3 potential harmful effects of hard collar use in this patient (3 marks)"},{"id":"c","label":"Part C","prompt":"List 4 clinical features which would suggest this patient has a critical vascular injury\n(4 marks)"},{"id":"d","label":"Part D","prompt":"Given his mechanism of injury you are concerned he may have sustained an acute\ncord injury. List 2 possible acute spinal cord syndromes in this case and identify 2\nassociated clinical findings (4 marks) Acute Cord Syndrome Clinical Finding"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">i.</div><div class=\"answer-line\">-Haemorrhage control with direct pressure, care not to obstruct airway due to</div><div class=\"answer-line\">compression</div><div class=\"answer-line\">-IV access x2 large bore; resuscitation with O negative PRBC</div><div class=\"answer-line\">-Airway control; high risk/difficult airway; most experienced airway practitioner with</div><div class=\"answer-line\">use of VL; Consider intubating trachea directly if visible through wound; performed</div><div class=\"answer-line\">with care as possible to convert to complete transection</div><div class=\"answer-line\">-RSI with neuroprotective strategies</div><div class=\"answer-line\">-MILS given potential c-spine injury</div><div class=\"answer-line\">-Management of combative behaviour to enable overall assessment (and to achieve</div><div class=\"answer-line\">above safely); ketamine for analgesia and dissociative effects</div><div class=\"answer-line\">ii.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Obscuring of neck wound during assessment/management</div><div class=\"answer-line\">•</div><div class=\"answer-line\">Potentially exacerbate airway compromise</div><div class=\"answer-line\">•</div><div class=\"answer-line\">Potentially increase ICP due to impedance of venous return</div><div class=\"answer-line\">iii.</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Initial assessment:</td></tr><tr><td>GCS</td><td>10; combative</td></tr><tr><td>HR</td><td>125 per minute</td></tr><tr><td>BP</td><td>105/65 mmHg</td></tr><tr><td>Head:</td><td>Right parietal large boggy swelling</td></tr><tr><td>Neck:</td><td>Wound at right side of anterior neck, extends from medial aspect of</td></tr><tr><td colspan=\"2\">clavicle to level of cricoid, extensive haemorrhage</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">-Haemorrhage control with direct pressure, care not to obstruct airway due to</td></tr><tr><td colspan=\"2\">compression</td></tr><tr><td colspan=\"2\">-IV access x2 large bore; resuscitation with O negative PRBC</td></tr><tr><td colspan=\"2\">-Airway control; high risk/difficult airway; most experienced airway practitioner with</td></tr><tr><td colspan=\"2\">use of VL; Consider intubating trachea directly if visible through wound; performed</td></tr><tr><td colspan=\"2\">with care as possible to convert to complete transection</td></tr><tr><td colspan=\"2\">-RSI with neuroprotective strategies</td></tr><tr><td colspan=\"2\">-MILS given potential c-spine injury</td></tr><tr><td colspan=\"2\">-Management of combative behaviour to enable overall assessment (and to achieve</td></tr><tr><td colspan=\"2\">above safely); ketamine for analgesia and dissociative effects</td></tr><tr><td colspan=\"2\">ii.</td></tr><tr><td>•</td><td>Obscuring of neck wound during assessment/management</td></tr><tr><td>•</td><td>Potentially exacerbate airway compromise</td></tr><tr><td>•</td><td>Potentially increase ICP due to impedance of venous return</td></tr><tr><td colspan=\"2\">iii.</td></tr><tr><td colspan=\"2\">NSW Fellowship Course – NSLHD SAQ December 2017</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":15,"title":"","stemText":"(15 marks) An elderly lady is brought to your ED by ambulance. She was found by a neighbour in her back yard.\n\nVital signs:\n\nGCS 9 (E3V3M3)\n\nBP 90/50 mmHg\n\nHR 45 bpm\n\nSaO2 90% (8L/min Hudson)\n\nTemp 27 deg celsius (oral and rectal)","parts":[{"id":"a","label":"Part A","prompt":"List possible complications of her hypothermia on four organ systems (4 marks)"},{"id":"b","label":"Part B","prompt":"After one hour, the patient remains GCS 9 and temp 29 degrees despite initial treatment. You decide to perform a CT brain. List 3 pros and 3 cons of intubating prior to CT (6 marks)"},{"id":"c","label":"Part C","prompt":"The patient develops ventricular fibrillation. List five ways in which your approach to this resuscitation differs from standard ALS principles (5 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">i.</div><div class=\"answer-line\">• Respiratory – respiratory depression, suppressed gag/cough, aspiration</div><div class=\"answer-line\">• Cardiac – bradycardia, hypotension, arrhythmia (AF,VF)</div><div class=\"answer-line\">• CNS – decreased LOC</div><div class=\"answer-line\">• Renal – AKI, rhabdomyolysis</div><div class=\"answer-line\">• Haematologic – thrombosis, DIC</div><div class=\"answer-line\">• Metabolic – met and resp acidosis</div><div class=\"answer-line\">• Pancreatitis</div><div class=\"answer-line\">ii.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• Pros</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">o Optimises oxygenation if this is compromised</div><div class=\"answer-line\">o Optimal conditions for high quality CT – pt immobile</div><div class=\"answer-line\">• Cons</div><div class=\"answer-line\">o High risk of arrhythmia with manipulation of airway</div><div class=\"answer-line\">NSW Fellowship Course – NSLHD SAQ December 2017</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":16,"title":"","stemText":"A 29 year old male is brought in by ambulance after a collapse at work. He is a machine\n• perator at a nearby 24 hour factory. Colleagues report he collapsed to the ground whilst\nworking. He was unresponsive and jerking all limbs for a brief period. His level of consciousness has improved on transport to ED.\n\nVital signs\n\nGCS 15\n\nHR 90 bpm\n\nBP 126/84 mmHg\n\nTemp 37.5 deg C\n\nSaO2 100% (6L/min Hudson)","parts":[{"id":"a","label":"Part A","prompt":"List four possible causes for his collapse (4 marks)"},{"id":"b","label":"Part B","prompt":"List four features on history and examination that may suggest that this is a seizure rather than another cause for collapse (4 marks)"},{"id":"c","label":"Part C","prompt":"List four reasons why you would order an urgent CT brain (4 marks)"},{"id":"d","label":"Part D","prompt":"Describe four considerations in determining that this man is fit for discharge home (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• Cardiac arrhythmia</div><div class=\"answer-line\">• Vasovagal syncope</div><div class=\"answer-line\">• Seizure disorder ie epilepsy</div><div class=\"answer-line\">• Trauma – HI</div><div class=\"answer-line\">• CNS infection – meningitis/encephalitis</div><div class=\"answer-line\">• CNS bleed  – SAH, ICB</div><div class=\"answer-line\">• Other intracranial – SOL,  thrombo-embolic stroke,</div><div class=\"answer-line\">• Metabolic  - hi/lo BSL, hi/lo Na, low Ca, renal/hepatic failure</div><div class=\"answer-line\">• Drugs/Toxins – ETOH, anticholinergics,  sympathomimetics (amphetamine, cocaine, ICE),</div><div class=\"answer-line\">phenothiazines,  organophosphates</div><div class=\"answer-line\">• Drug withdrawal – ETOH, benzos, opioids, cocaine, anticonvulsants</div><div class=\"answer-line\">• Pseudoseizure</div><div class=\"answer-line\">• Electrocution</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">List four features on history and examination that may suggest that this is a seizure</div><div class=\"answer-line\">rather than another cause for collapse (4 marks)</div><div class=\"answer-line\">NSW Fellowship Course – NSLHD SAQ December 2017</div><div class=\"answer-line\">• Past history of seizures</div><div class=\"answer-line\">• Time course – sudden onset/offset, brief – usually less than 2 minutes</div><div class=\"answer-line\">• Description of attack – involuntary movement, incontinence, tongue biting (and location</div><div class=\"answer-line\">of tongue injury), drooling</div><div class=\"answer-line\">• Amnesia</div><div class=\"answer-line\">• Post ictal period – confusion, lethargy</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">• Focal neurological symptoms/signs</div><div class=\"answer-line\">• Persistent reduced LOC</div><div class=\"answer-line\">• Further unexplained seizure activity in ED</div><div class=\"answer-line\">• Bleeding disorder</div><div class=\"answer-line\">• Fever or suspected CNS infection</div><div class=\"answer-line\">• Past H/O intracranial pathology or malignancy</div><div class=\"answer-line\">• Suspected SAH</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Describe four considerations in determining that this man is fit for discharge home (4</div><div class=\"answer-line\">marks)</div><div class=\"answer-line\">NSW Fellowship Course – NSLHD SAQ December 2017</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":17,"title":"","stemText":"Pre-hospital bypass of smaller centres directly to designated trauma centres is routine practice in many metropolitan environments","parts":[{"id":"a","label":"Part A","prompt":"List the criteria used by paramedics to determine which trauma patients should\nbypass smaller centres ( 6 marks)"},{"id":"b","label":"Part B","prompt":"Describe the main difficulty arising from the inclusion of mechanism of injury as part\n• f a triage tool (2 marks)"},{"id":"c","label":"Part C","prompt":"List 2 advantages and 2 disadvantages of trauma bypass (4 marks)"},{"id":"d","label":"Part D","prompt":"A long distance to reach a major trauma service requires paramedics to manage patients en route. In what circumstances does the evidence support “permissive hypotension” in the pre-hospital setting? (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">NSW Fellowship Course – NSLHD SAQ December 2017</div><div class=\"answer-line\">Varies between jurisdictions.  Usually based on “MIS(T)” criteria.</div><div class=\"answer-line\">Mechanism:  Vehicle crash at over 60km/h ❑  Major deformation of the vehicle,</div><div class=\"answer-line\">entrapment &gt;30 minutes ❑  Fatal injury in the same vehicle, ejection from the vehicle ❑</div><div class=\"answer-line\">Fall from over 3 meters ❑  Unrestrained child in a motor vehicle crash ❑  Cyclist or</div><div class=\"answer-line\">pedestrian hit by vehicle at over 30km/h, driveway run-over injuries ❑  Caustic ingestions -</div><div class=\"answer-line\">liquid or powder in children ❑  Any mechanism causing injuries to multiple body regions ❑</div><div class=\"answer-line\">CHILDREN: Driveway run-over injuries ❑  CHILDREN: Caustic ingestion – liquid or powder</div><div class=\"answer-line\">Injuries:  Penetrating injury to head, neck, chest, abdomen, perineum, or back ❑  Head</div><div class=\"answer-line\">injury with coma, a dilated pupil, open head injury, or severe facial injury ❑  Chest injury</div><div class=\"answer-line\">with flail segment or subcutaneous emphysema ❑  Abdominal injury with distension</div><div class=\"answer-line\">and/or rigidity ❑  Spinal injury with weakness and/or sensory loss ❑  Limb injury involving</div><div class=\"answer-line\">vascular injury with ischaemia of the limb, amputation, crush injury of the limb or trunk, or</div><div class=\"answer-line\">bilateral fractures of the femur, complex pelvic injury ❑  Burns, partial or full thickness,</div><div class=\"answer-line\">more than 20% in adults, or more than 10% in children ❑  CHILDREN: Burns, partial or full</div><div class=\"answer-line\">thickness, more than 10% in children</div><div class=\"answer-line\">Signs: Respiratory distress - less than 10 or more than 30 breaths per minute and/or</div><div class=\"answer-line\">cyanosis ❑  Systolic blood pressure less than 90 or pulse greater than 130 ❑  Difficulty in</div><div class=\"answer-line\">arousal, or falling level of consciousness, GCS&lt;13</div><div class=\"answer-line\">ii.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">High degree of sensitivity but poor specificity for predicting severe trauma. Results in</div><div class=\"answer-line\">significant over-triage</div><div class=\"answer-line\">iii.</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Option</th><th>Advantage</th><th>Disadvantage</th></tr></thead><tbody><tr><td>Varies between jurisdictions.  Usually based on “MIS(T)” criteria.</td><td></td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Mechanism:  Vehicle crash at over 60km/h ❑  Major deformation of the vehicle,</div><div class=\"answer-line\">entrapment &gt;30 minutes ❑  Fatal injury in the same vehicle, ejection from the vehicle ❑</div><div class=\"answer-line\">Fall from over 3 meters ❑  Unrestrained child in a motor vehicle crash ❑  Cyclist or</div><div class=\"answer-line\">pedestrian hit by vehicle at over 30km/h, driveway run-over injuries ❑  Caustic ingestions -</div><div class=\"answer-line\">liquid or powder in children ❑  Any mechanism causing injuries to multiple body regions ❑</div><div class=\"answer-line\">CHILDREN: Driveway run-over injuries ❑  CHILDREN: Caustic ingestion – liquid or powder</div><div class=\"answer-line\">Injuries:  Penetrating injury to head, neck, chest, abdomen, perineum, or back ❑  Head</div><div class=\"answer-line\">injury with coma, a dilated pupil, open head injury, or severe facial injury ❑  Chest injury</div><div class=\"answer-line\">with flail segment or subcutaneous emphysema ❑  Abdominal injury with distension</div><div class=\"answer-line\">and/or rigidity ❑  Spinal injury with weakness and/or sensory loss ❑  Limb injury involving</div><div class=\"answer-line\">vascular injury with ischaemia of the limb, amputation, crush injury of the limb or trunk, or</div><div class=\"answer-line\">bilateral fractures of the femur, complex pelvic injury ❑  Burns, partial or full thickness,</div><div class=\"answer-line\">more than 20% in adults, or more than 10% in children ❑  CHILDREN: Burns, partial or full</div><div class=\"answer-line\">thickness, more than 10% in children</div><div class=\"answer-line\">Signs: Respiratory distress - less than 10 or more than 30 breaths per minute and/or</div><div class=\"answer-line\">cyanosis ❑  Systolic blood pressure less than 90 or pulse greater than 130 ❑  Difficulty in</div><div class=\"answer-line\">arousal, or falling level of consciousness, GCS&lt;13</div><div class=\"answer-line\">ii.</div><div class=\"answer-line\">of a triage tool (2 marks)</div><div class=\"answer-line\">High degree of sensitivity but poor specificity for predicting severe trauma. Results in</div><div class=\"answer-line\">significant over-triage</div><div class=\"answer-line\">iii.</div><div class=\"answer-line\">NSW Fellowship Course – NSLHD SAQ December 2017</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":18,"title":"","stemText":"A 17 year old male is brought your district ED by his nurse mother after feeling dizzy and unwell and appearing ‘pale’ on the football field. He was reluctant to attend as he felt ‘fine’.\nPresenting blood pressure 115/60. Saturations 99% on room air. RR 14. Afebrile. Triage\nECG performed.","parts":[{"id":"a","label":"Part A","prompt":"Describe and interpret his ECG (5 marks) SEE PROPS BOOKLET - IMAGE G"},{"id":"b","label":"Part B","prompt":"List up to 5 questions you would like to ask on history, regarding symptoms (5\nmarks)"},{"id":"c","label":"Part C","prompt":"List and justify up to 3 initial investigations you would like to perform (3 marks)"},{"id":"d","label":"Part D","prompt":"Prior to any further investigation, he tells you he wants to discharge against your advice. List your management priorities now (3 marks)"}],"propPages":["asset:img5c462365e62970968c"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">NSW Fellowship Course – NSLHD SAQ December 2017</td></tr><tr><td colspan=\"2\">1 mark for -</td></tr><tr><td>•</td><td>SR  approx 50 bpm</td></tr><tr><td>•</td><td>Leftward axis 1 postive 2 equiphasic 3 negative</td></tr><tr><td>•</td><td>PR  interval – ok if described short (borderline – 30% assoc. with WPW)</td></tr><tr><td colspan=\"2\">3 marks for–</td></tr><tr><td>•</td><td>Q waves – dagger Q’s V1-5 (with narrow complex QRS)</td></tr><tr><td>•</td><td>LVH by voltage</td></tr><tr><td>•</td><td>Diffuse ST/T changes with T wave inversion chest leads V2-5</td></tr><tr><td colspan=\"2\">Interpretation – 1 mark</td></tr><tr><td>•</td><td>Highly suspicious for HCM (or HOCM)</td></tr><tr><td colspan=\"2\">List up to 5  questions you would like to ask on history, regarding symptoms (5</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">marks)</td></tr><tr><td>•</td><td>Exertional  – presyncope or syncope</td></tr><tr><td>•</td><td>Lung symptoms – dyspnoea rest and exertional, PND, orthopnea. Etc</td></tr><tr><td>•</td><td>Palpitations -  atrial and vent. Dysrhythmia</td></tr><tr><td>•</td><td>Chest pain -  anginal</td></tr><tr><td>•</td><td>Family hx -  cardiac sudden death/known HCM</td></tr><tr><td>•</td><td>(?prior Ix/Echo)</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"3\">NSW Fellowship Course – NSLHD SAQ December 2017</td></tr><tr><td>•</td><td>Bedside</td><td>serial ECG for dynamic changes</td></tr><tr><td>•</td><td>Bloods</td><td>troponin  -  ischaemia (+/_ serial)</td></tr><tr><td>•</td><td>CXR</td><td>cardiomegaly, pulmonary congestion</td></tr><tr><td>•</td><td>Cardiac Echo</td><td>?hypertrophy ?dynamic outflow obstruction, wall motion abnormality etc</td></tr><tr><td>•</td><td>Can have one of fbc.tft.bsl (something sensible) – alternative dx for symptoms</td><td></td></tr><tr><td colspan=\"3\">Prior to any further investigation, he tells you he wants to discharge against your</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Counsel patient as to ddx and possible severity/ramification e.g. sudden death</td></tr><tr><td>•</td><td>Mother/responsible guardian involvement as technically minor under 18 (but could give</td></tr><tr><td colspan=\"2\">valid consent to treatment being over 16)</td></tr><tr><td>•</td><td>?capacity assessment  -  retain, understand etc.</td></tr><tr><td>•</td><td>(Other colleague involvement early e.g. expedite cardio r/v/Echo if able)</td></tr><tr><td>•</td><td>Documentation</td></tr><tr><td>•</td><td>Something sensible!</td></tr><tr><td colspan=\"2\">NSW Fellowship Course – NSLHD SAQ December 2017</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false}];
